 function setControlMode(mode,{persist=true}={}){controlMode=mode==='buttons'?'buttons':'gestures';resetInput();doc.body.classList.toggle('gesture-mode',controlMode==='gestures');$('control-mode').value=controlMode;$('control-help').textContent=controlsHelp();$('control-guide').textContent=controlMode==='gestures'?'Left: drag · Right: tap to jump, swipe to dash. Tap nearby glowing objects. Controls option inside pause.':'Move, jump and dash with buttons. Hold the gold ACTION button near an object.';if(persist)saveControlMode(store,controlMode);}
