 function show(kicker,title,message,button){doc.body.classList.toggle('playing',false);$('kicker').textContent=kicker;$('title').textContent=title;$('message').textContent=message;$('play').textContent=button;$('overlay').hidden=false;$('pause-actions').hidden=!paused;$('return-home').hidden=run.status!=='won';$('play').classList.toggle('replay',run.status==='won');recordsLine();}
